package com.assetsphere.modules.workspace;
import java.nio.charset.StandardCharsets; import java.security.*; import java.time.Instant; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.assetsphere.modules.audit.*; import com.assetsphere.modules.audit.domain.AuditAction; import com.assetsphere.modules.common.*; import com.assetsphere.modules.workspace.api.*; import com.assetsphere.modules.workspace.domain.*; import com.assetsphere.modules.workspace.dto.WorkspaceRequests.*; import com.assetsphere.modules.workspace.dto.WorkspaceResponses.*;
@Service public class WorkspaceService implements WorkspaceFacade { private static final SecureRandom RANDOM=new SecureRandom(); private final WorkspaceRepository workspaces; private final WorkspaceMemberRepository members; private final WorkspaceInvitationRepository invitations; private final WorkspaceAuthorization authorization; private final ClockProvider clock; private final long invitationExpirationSeconds; private final AuditService audit;
 public WorkspaceService(WorkspaceRepository w,WorkspaceMemberRepository m,WorkspaceInvitationRepository i,WorkspaceAuthorization a,ClockProvider c,@Value("${assetsphere.security.invitation-expiration-seconds}") long invitationExpirationSeconds,AuditService audit){workspaces=w;members=m;invitations=i;authorization=a;clock=c;this.invitationExpirationSeconds=invitationExpirationSeconds;this.audit=audit;}
 @Override @Transactional public WorkspaceSummary createPersonalWorkspace(UUID userId,String displayName){String slug="personal-"+userId; Workspace workspace=workspaces.save(new Workspace(displayName.trim()+" Workspace",slug,null,userId));members.save(new WorkspaceMember(workspace.getId(),userId,WorkspaceRole.OWNER,userId,clock.now()));audit.record(userId,AuditAction.WORKSPACE_CREATED,workspace.getId(),"WORKSPACE",workspace.getId(),"{\"personal\":true}");return summary(workspace,WorkspaceRole.OWNER);}
 @Override @Transactional(readOnly=true) public List<WorkspaceSummary> findWorkspacesForUser(UUID userId){return members.findByUserIdAndStatus(userId,MembershipStatus.ACTIVE).stream().map(m->workspaces.findById(m.getWorkspaceId()).map(w->summary(w,m.getRole())).orElse(null)).filter(Objects::nonNull).toList();}
 @Transactional public Detail create(UUID actor,Create request){try{Workspace w=workspaces.save(new Workspace(request.name().trim(),SlugNormalizer.normalize(request.slug()),request.description(),actor));members.save(new WorkspaceMember(w.getId(),actor,WorkspaceRole.OWNER,actor,clock.now()));audit.record(actor,AuditAction.WORKSPACE_CREATED,w.getId(),"WORKSPACE",w.getId(),"{}");return detail(w);}catch(DataIntegrityViolationException e){throw new BusinessRuleViolationException("Workspace slug is already in use");}}
 @Transactional(readOnly=true) public Detail get(UUID actor,UUID id){authorization.requireMembership(id,actor);return detail(requireWorkspace(id));}
 @Transactional public Detail update(UUID actor,UUID id,Update request){authorization.requireAnyRole(id,actor,WorkspaceRole.OWNER,WorkspaceRole.ADMIN);Workspace w=requireWorkspace(id);w.update(request.name()==null?null:request.name().trim(),request.description());audit.record(actor,AuditAction.WORKSPACE_UPDATED,id,"WORKSPACE",id,"{}");return detail(w);}
 @Transactional(readOnly=true) public List<Member> listMembers(UUID actor,UUID id){authorization.requireMembership(id,actor);return members.findByWorkspaceIdAndStatus(id,MembershipStatus.ACTIVE).stream().map(this::member).toList();}
 @Transactional public Invitation invite(UUID actor,UUID id,Invite request){authorization.requireAnyRole(id,actor,WorkspaceRole.OWNER,WorkspaceRole.ADMIN);WorkspaceMember inviter=members.findByWorkspaceIdAndUserId(id,actor).orElseThrow();if(request.role()==WorkspaceRole.OWNER&&inviter.getRole()!=WorkspaceRole.OWNER)throw new AuthorizationDeniedException("Only an owner may grant the owner role");String email=EmailNormalizer.normalize(request.email());invitations.findByWorkspaceIdAndInviteeEmailAndStatus(id,email,InvitationStatus.PENDING).ifPresent(x->{throw new BusinessRuleViolationException("A pending invitation already exists");});String raw=randomToken();WorkspaceInvitation invitation=invitations.save(new WorkspaceInvitation(id,email,request.role(),hash(raw),actor,clock.now().plusSeconds(invitationExpirationSeconds)));audit.record(actor,AuditAction.WORKSPACE_MEMBER_INVITED,id,"WORKSPACE_INVITATION",invitation.getId(),"{}");return new Invitation(invitation.getId(),email,request.role().name(),invitation.getExpiresAt(),raw);}
 @Transactional public Member accept(UUID actor,String email,Accept request){WorkspaceInvitation invite=invitations.findByTokenHash(hash(request.invitationToken())).orElseThrow(()->new BusinessRuleViolationException("Invitation is invalid"));Instant now=clock.now();if(!invite.getInviteeEmail().equals(EmailNormalizer.normalize(email)))throw new AuthorizationDeniedException("Invitation email does not match authenticated user");if(invite.getStatus()==InvitationStatus.ACCEPTED){return members.findByWorkspaceIdAndUserId(invite.getWorkspaceId(),actor).map(this::member).orElseThrow(()->new BusinessRuleViolationException("Invitation was already accepted"));}if(!invite.isPending())throw new BusinessRuleViolationException("Invitation is not pending");if(invite.isExpired(now)){invite.expire();throw new BusinessRuleViolationException("Invitation has expired");}WorkspaceMember member=members.findByWorkspaceIdAndUserId(invite.getWorkspaceId(),actor).orElseGet(()->members.save(new WorkspaceMember(invite.getWorkspaceId(),actor,invite.getRole(),invite.getInvitedByUserId(),now)));invite.accept(now);audit.record(actor,AuditAction.WORKSPACE_INVITATION_ACCEPTED,invite.getWorkspaceId(),"WORKSPACE_INVITATION",invite.getId(),"{}");return member(member);}
 @Transactional public Member changeRole(UUID actor,UUID workspaceId,UUID memberId,ChangeRole request){authorization.requireAnyRole(workspaceId,actor,WorkspaceRole.OWNER);WorkspaceMember m=requireMember(workspaceId,memberId);if(m.getRole()==WorkspaceRole.OWNER&&request.role()!=WorkspaceRole.OWNER&&members.countByWorkspaceIdAndStatusAndRole(workspaceId,MembershipStatus.ACTIVE,WorkspaceRole.OWNER)<=1)throw new BusinessRuleViolationException("A workspace must retain an active owner");m.changeRole(request.role());audit.record(actor,AuditAction.WORKSPACE_MEMBER_ROLE_CHANGED,workspaceId,"WORKSPACE_MEMBER",memberId,"{}");return member(m);}
 @Transactional public void remove(UUID actor,UUID workspaceId,UUID memberId){authorization.requireAnyRole(workspaceId,actor,WorkspaceRole.OWNER,WorkspaceRole.ADMIN);WorkspaceMember target=requireMember(workspaceId,memberId);WorkspaceMember requester=members.findByWorkspaceIdAndUserId(workspaceId,actor).orElseThrow();if(requester.getRole()==WorkspaceRole.ADMIN&&target.getRole()!=WorkspaceRole.MEMBER&&target.getRole()!=WorkspaceRole.VIEWER&&target.getRole()!=WorkspaceRole.AUDITOR)throw new AuthorizationDeniedException("An administrator cannot remove an owner or another administrator");if(target.getRole()==WorkspaceRole.OWNER&&members.countByWorkspaceIdAndStatusAndRole(workspaceId,MembershipStatus.ACTIVE,WorkspaceRole.OWNER)<=1)throw new BusinessRuleViolationException("A workspace must retain an active owner");target.remove();audit.record(actor,AuditAction.WORKSPACE_MEMBER_REMOVED,workspaceId,"WORKSPACE_MEMBER",memberId,"{}");}
 private Workspace requireWorkspace(UUID id){return workspaces.findById(id).orElseThrow(()->new ResourceNotFoundException("Workspace not found"));} private WorkspaceMember requireMember(UUID w,UUID id){WorkspaceMember m=members.findById(id).orElseThrow(()->new ResourceNotFoundException("Workspace member not found"));if(!m.getWorkspaceId().equals(w))throw new ResourceNotFoundException("Workspace member not found");return m;} private WorkspaceSummary summary(Workspace w,WorkspaceRole r){return new WorkspaceSummary(w.getId(),w.getName(),w.getSlug(),r.name());} private Detail detail(Workspace w){return new Detail(w.getId(),w.getName(),w.getSlug(),w.getDescription(),w.getStatus().name());} private Member member(WorkspaceMember m){return new Member(m.getId(),m.getUserId(),m.getRole().name(),m.getStatus().name(),m.getJoinedAt());} private String randomToken(){byte[] b=new byte[48];RANDOM.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);} private String hash(String raw){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
